import { spawnSync } from 'child_process';
import fs from 'fs';
import path from 'path';

const S = 'bug6969-4382d7d38d88';
const base = 'http://localhost:8162';
const tok = fs.readFileSync(path.join(process.env.TEMP, 'flood-token-bug6969.txt'), 'utf8');
const tokJson = JSON.stringify(tok);

function ab(...args) {
  const r = spawnSync('agent-browser', ['--session', S, ...args], { encoding: 'utf8', shell: true });
  return (r.stdout || '') + (r.stderr || '');
}

ab('open', `${base}/#/pages/login/index`);
ab('eval', `sessionStorage.setItem('flood-token-v1',${tokJson});sessionStorage.setItem('flood-login-user-v1','{}');`);

const measureJs = `(() => {
  const start = performance.now();
  location.replace('${base}/#/pages/history/index');
  return new Promise(resolve => {
    const samples = [];
    const tick = () => {
      const ms = Math.round(performance.now() - start);
      const btn = [...document.querySelectorAll('button')].find(b => (b.textContent || '').includes('全部工单'));
      const text = btn ? btn.textContent.replace(/\\s+/g, ' ').trim() : '';
      const hasNum = /\\(\\d+\\)/.test(text);
      const skeleton = btn && text.includes('全部工单') && !hasNum;
      samples.push({ ms, text: text.slice(0, 40), skeleton, hasNum });
      if (hasNum) {
        resolve(JSON.stringify({ doneMs: ms, samples, final: text }));
        return;
      }
      if (ms > 6000) {
        resolve(JSON.stringify({ doneMs: null, samples, final: text }));
        return;
      }
      setTimeout(tick, 40);
    };
    setTimeout(tick, 0);
  });
})()`;

const out = ab('eval', measureJs);
console.log('MEASURE', out.trim());

const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const shot = path.join(process.env.TEMP, `zentao-bug6969-timing-${ts}.png`);
ab('screenshot', shot);
console.log('SHOT', shot);

